import fs from 'fs/promises';

/*
 * Lightweight, honest photo-metadata check.
 * It looks for editing / AI-tool markers and provenance tags embedded in the file and for missing camera (EXIF) data.
 * This is a SIGNAL for the manual-review queue, never proof that a photo is fake or genuine.
 */
const MARKERS = [
  'midjourney', 'dall-e', 'dall·e', 'stable diffusion', 'stablediffusion', 'firefly', 'openai',
  'c2pa', 'jumbf', 'synthid', 'leonardo.ai', 'comfyui', 'automatic1111', 'generated by ai', 'ai generated',
  'adobe photoshop', 'canva'
];

async function inspect(filePath) {
  const buf = await fs.readFile(filePath);
  const text = buf.toString('latin1').toLowerCase();
  if (MARKERS.some(m => text.includes(m))) return 'signal';
  // JPEG 'Exif', PNG 'eXIf' and WebP 'EXIF' chunks all contain this tag name once lower-cased.
  return text.includes('exif') ? 'ok' : 'nometa';
}

// Returns one of the Listing.reviewStatus values.
export async function analyseUploads(files = []) {
  if (!files.length) return 'Pending Review';
  try {
    const results = await Promise.all(files.map(f => inspect(f.path)));
    if (results.includes('signal')) return 'Signal Detected';
    if (results.includes('nometa')) return 'Inconclusive';
  } catch (err) {
    console.error('Image metadata check failed:', err.message);
    return 'Inconclusive';
  }
  return 'Pending Review';
}
